,p_display_sequence=>20
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT r.headcount,',
'           r.dept_id,',
'           r.requested_by,',
'           j.title,',
'           d.name',
'      INTO :V_REQUESTED_HEADCOUNT,',
'           :V_DEPARTMENT_ID,',
'           :V_REQUESTER_ID,',
'           :V_JOB_TITLE,',
'           :V_DEPARTMENT_NAME',
'      FROM tms_job_requisitions r',
'      JOIN tms_jobs j ON j.job_id = r.job_id',
'      JOIN tms_departments d ON d.dept_id = r.dept_id',
'     WHERE r.req_id = :P_REQ_ID;',
'END;'))
