prompt --application/shared_components/automations/interview_reminder
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(5637435265441313245)
,p_name=>'Interview Reminder'
,p_static_id=>'interview-reminder'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=7;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    i.stage_id,',
'    i.stage_name,',
'    i.scheduled_date AS interview_date,',
'    TO_CHAR(i.scheduled_date, ''DD-Mon-YYYY HH24:MI'') AS interview_date_text,',
'    c.first_name || '' '' || c.last_name AS candidate_name,',
'    e.email AS interviewer_email,',
'    e.first_name || '' '' || e.last_name AS interviewer_name',
'FROM tms_interview_stages i',
'JOIN tms_candidates c',
'    ON c.candidate_id = i.candidate_id',
'JOIN tms_employees e',
'    ON e.employee_id = i.interviewer_id',
'WHERE TRUNC(i.scheduled_date) = TRUNC(SYSDATE) + 1'))
,p_commit_each_row=>false
,p_error_handling_type=>'ABORT'
);
