 p_id=>wwv_flow_imp.id(5637962902811065653)
,p_name=>'Offer Expiry Alert'
,p_static_id=>'offer-expiry-alert'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=8;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    o.offer_id,',
'    o.candidate_id,',
'    o.expiry_date,',
'    c.first_name || '' '' || c.last_name AS candidate_name,',
'    o.offered_salary,',
'    r.requested_by AS recruiter_email',
'FROM tms_offers o',
'JOIN tms_candidates c',
'    ON c.candidate_id = o.candidate_id',
'JOIN tms_job_requisitions r',
'    ON r.req_id = o.req_id',
'WHERE o.status = ''Sent''',
'  AND o.expiry_date = TRUNC(SYSDATE) + 3'))
,p_commit_each_row=>false
,p_error_handling_type=>'ABORT'
);
