'GROUP  BY current_stage',
'ORDER  BY Decode(current_stage, ''Applied'', 1,',
'                                ''Screening'', 2,',
'                                ''Interview'', 3,',
'                                ''Offer'', 4,',
'                                ''Hired'', 5,',
