 p_id=>wwv_flow_imp.id(4623774168842840423)
,p_plug_name=>'Salary Band Indicator'
,p_static_id=>'salary-band-indicator'
,p_parent_plug_id=>wwv_flow_imp.id(4587767479887495753)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>3374665444246510938
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_salary NUMBER := TO_NUMBER(',
'        REGEXP_REPLACE(NVL(:P9_OFFERED_SALARY, ''0''), ''[^0-9.\-]'', '''')',
'    );',
'    l_min   NUMBER := NVL(TO_NUMBER(:P9_MIN_SALARY), 0);',
'    l_max   NUMBER := NVL(TO_NUMBER(:P9_MAX_SALARY), 0);',
'    l_pct   NUMBER := 0;',
'    l_color VARCHAR2(20) := ''#10b981'';',
'BEGIN',
'    IF l_max > l_min THEN',
'        l_pct := ROUND(',
'            GREATEST(0, LEAST(1, (l_salary - l_min) / (l_max - l_min))) * 100',
'        );',
'    END IF;',
'',
'    IF l_salary > l_max THEN',
'        l_color := ''#ef4444'';',
'    ELSIF l_pct > 80 THEN',
'        l_color := ''#f59e0b'';',
'    END IF;',
'',
'    RETURN',
'        ''<div style="background:#e5e7eb;border-radius:8px;height:12px;overflow:hidden">''',
'        || ''<div style="height:12px;width:'' || l_pct || ''%;background:'' || l_color || '';border-radius:8px"></div>''',
'        || ''</div>''',
'        || ''<p style="font-size:12px;margin-top:4px;color:#6b7280">''',
'        || l_pct || ''% of band</p>'';',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P9_MIN_SALARY,P9_MAX_SALARY,P9_OFFERED_SALARY'
);
