,p_plug_name=>'Interview Calendar'
,p_static_id=>'interview-calendar'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    i.stage_id AS event_id,',
'    c.first_name || '' '' || c.last_name ||',
'        '' - '' || i.stage_name AS event_title,',
'    i.scheduled_date AS start_date,',
'    i.scheduled_date + (1 / 24) AS end_date,',
'    i.candidate_id,',
'    i.outcome',
'FROM tms_interview_stages i',
'JOIN tms_candidates c',
'    ON c.candidate_id = i.candidate_id',
'JOIN tms_employees e',
'    ON e.employee_id = i.interviewer_id',
'WHERE UPPER(e.email) = UPPER(:APP_USER)'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'additional_calendar_views', 'list:navigation',
  'display_column', 'EVENT_TITLE',
  'end_date_column', 'END_DATE',
  'event_sorting', 'AUTOMATIC',
  'maximum_events_day', '10',
  'multiple_line_event', 'Y',
  'responsive_list_view', 'Y',
  'show_time', 'N',
  'show_tooltip', 'Y',
  'show_weekend', 'Y',
  'start_date_column', 'START_DATE',
  'view_edit_link', 'f?p=&APP_ID.:13:&SESSION.::&DEBUG.::P13_CANDIDATE_ID,P13_SCHEDULED_DATE:&CANDIDATE_ID.,&START_DATE.')).to_clob
);
