wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5658204132927750236)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Offer'
,p_static_id=>'create-offer'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'l_cand_id NUMBER;',
'l_job_id  NUMBER;',
'l_req_id  NUMBER;',
'l_salary  NUMBER;',
'l_start   DATE;',
'l_expiry  DATE;',
'BEGIN',
'SELECT TO_NUMBER(c001),',
'       TO_NUMBER(c002),',
'       n001,',
'       d001,',
'       d002',
'INTO   l_cand_id,',
'       l_job_id,',
'       l_salary,',
'       l_start,',
'       l_expiry',
'FROM apex_collections',
'WHERE collection_name = ''OFFER_COLLECTION''',
'  AND seq_id = 1;',
'',
'SELECT req_id',
'INTO   l_req_id',
'FROM   tms_job_requisitions',
'WHERE  job_id = l_job_id',
'AND    status = ''Open''',
'AND    ROWNUM = 1;',
'',
'INSERT INTO tms_offers (',
'    candidate_id,',
'    req_id,',
'    offered_salary,',
'    start_date,',
'    expiry_date,',
'    status',
')',
'VALUES (',
'    l_cand_id,',
'    l_req_id,',
'    l_salary,',
'    l_start,',
'    l_expiry,',
'    ''Sent''',
')',
'RETURNING offer_id INTO :P19_OFFER_ID;',
'',
'apex_collection.delete_collection(''OFFER_COLLECTION'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>5658204132927750236
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5658204226981750237)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
