'-- reactivated without changing their original assignment timestamp.'||wwv_flow.LF||
'MERGE INTO tms_employee_roles ';
wwv_flow_imp.g_varchar2_table(74) := 'target'||wwv_flow.LF||
'USING ('||wwv_flow.LF||
'  SELECT e.employee_id,'||wwv_flow.LF||
